package com.example.jposserver.config;

import org.jpos.q2.iso.QMUX;
import org.jpos.transaction.TransactionManager;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class JposConfig {

    @Bean
    public TransactionManager transactionManager() {
        TransactionManager tm = new TransactionManager();
        tm.setName("txnmgr");
        tm.setQueue("txnmgr");
        return tm;
    }

    @Bean
    public QMUX qmux() {
        QMUX qmux = new QMUX();
        qmux.setName("mux");
        qmux.setLogger("Q2");
        qmux.setRealm("mux");
        return qmux;
    }
}

package com.example.jposserver;

import org.jpos.q2.Q2;

public class JposServerApplication {
    public static void main(String[] args) {
        Q2 q2 = new Q2();
        q2.start();
    }
}

package com.example.jposserver;

import org.jpos.q2.Q2;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.ApplicationContext;

import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest
class JposServerApplicationTests {

    @Autowired
    private ApplicationContext applicationContext;

    @Test
    void contextLoads() {
        assertThat(applicationContext).isNotNull();
        assertThat(applicationContext.getBean(Q2.class)).isNotNull();
    }
}
